import axios from "axios";
import { resolvePreviewFetchUrl } from "../preview-resource-base";
async function loadAppExtensions() {
  try {
    const response = await axios.get(resolvePreviewFetchUrl("./app.extensions.js"), {
      responseType: "text"
    });
    if (response.data) {
      const script = document.createElement("script");
      script.textContent = response.data;
      document.head.appendChild(script);
    }
  } catch (e) {
  }
}
export {
  loadAppExtensions
};
